\version "2.27.2"
% automatically converted by musicxml2ly from 41k-PartName-Print.xml
\pointAndClickOff

\header {
  texidoc = "The <part-name-display> and <part-abbreviation-display> elements
    can also be children of the <print> element; the former is used at the
    beginning of the first bar, and the latter at the beginning of the second
    bar.

    The multi-line entries are generated by using ‘xml:space=\"preserve\"’ as an
    attribute within a <display-text> child of the <xxx-display> element. There
    are two empty lines between ‘Part’ and ‘Name’."
}
\layout {
  \context {
    \Score
    autoBeaming = ##f
  }
}
PartPOneVoiceOne = \relative c' {
  \set Staff.instrumentName = \markup \concat { \center-column { Part \null \null Name } }
  \once \omit Staff.TimeSignature c1 \break \set Staff.shortInstrumentName =
  \markup \concat { \center-column { "P." "N." } } | % 1
  c1 }


% The score definition
\score {
  <<
    \new Staff = "P1" <<
      \context Staff <<
        \override Staff.BarLine.allow-span-bar = ##f
        \mergeDifferentlyDottedOn
        \mergeDifferentlyHeadedOn
        \context Voice = "PartPOneVoiceOne" {
          \PartPOneVoiceOne
        }
      >>
    >>
  >>
  \layout {}
  % To create MIDI output, uncomment the following line:
  % \midi { \tempo 4 = 100 }
}
